//! Idempotent installer for native-agent settings-hooks (Claude, Gemini, Codex…).
//!
//! Writes the hook commands generated by [`crate::agent_hook`] into an agent's
//! JSON settings file and removes them again on demand. Ownership is decided
//! solely by the `# tuic-managed-hook` sentinel embedded in each command, so the
//! installer touches ONLY TUIC's entries — user and wiz hooks in the same file
//! are never read incorrectly, reordered, or destroyed.
//!
//! Invariants:
//! - **Single read-modify-write.** Load → rewrite our groups in place → prune
//!   the rest of ours → append missing groups → atomic write. The file is
//!   written exactly once, never on an error path, so a malformed settings file
//!   is reported (not corrupted).
//! - **Stable positions.** A reinstall keeps every group at its index. Codex
//!   keys hook trust by position (`hooks.json:stop:3:0`), so moving our group
//!   would shift a later hook onto another hook's trusted hash.
//! - **Idempotent.** Installing twice equals installing once.
//! - **Clean uninstall.** Pruning removes only sentineled commands and drops the
//!   groups/events that became empty as a result, leaving the file as if TUIC was
//!   never there.

use crate::agent_hook::{HookEntry, SENTINEL};
use serde_json::{Map, Value};
use std::path::Path;

/// Whether TUIC's hooks are present in a settings file, and current.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum InstallState {
    /// No TUIC-managed hooks present.
    NotInstalled,
    /// TUIC hooks present and byte-identical to the expected map.
    Installed,
    /// TUIC hooks present but differ from the expected map (older version).
    Outdated,
    /// Canonical Codex files need current native trust verification.
    ReviewRequired,
}

impl InstallState {
    /// Stable wire string for the frontend/HTTP (camelCase, matches the TS union).
    pub(crate) fn as_str(self) -> &'static str {
        match self {
            InstallState::NotInstalled => "notInstalled",
            InstallState::Installed => "installed",
            InstallState::Outdated => "outdated",
            InstallState::ReviewRequired => "reviewRequired",
        }
    }
}

fn is_tuic_managed(cmd: &str) -> bool {
    cmd.contains(SENTINEL)
}

/// Load the settings file as a JSON object, or a fresh empty object if the file
/// is missing or blank. Errors (leaving the file untouched) if the root exists
/// but is not a JSON object.
fn load_root(path: &Path) -> Result<Map<String, Value>, String> {
    if !path.exists() {
        return Ok(Map::new());
    }
    let bytes = std::fs::read(path).map_err(|e| format!("read {}: {e}", path.display()))?;
    if bytes.iter().all(u8::is_ascii_whitespace) {
        return Ok(Map::new());
    }
    match serde_json::from_slice(&bytes).map_err(|e| format!("parse {}: {e}", path.display()))? {
        Value::Object(m) => Ok(m),
        _ => Err(format!("{} root is not a JSON object", path.display())),
    }
}

/// Serialize and write atomically (0600, temp+rename via `config::persist_atomic`).
fn write_root(path: &Path, root: &Map<String, Value>) -> Result<(), String> {
    let bytes = serde_json::to_vec_pretty(&Value::Object(root.clone()))
        .map_err(|e| format!("serialize settings: {e}"))?;
    crate::config::persist_atomic(path, &bytes)
}

/// Remove every TUIC-managed command from all event groups, then drop the groups
/// and events that this pruning left empty (so the file is restored exactly).
/// A user's group that merely contained a TUIC command keeps its other hooks; a
/// group/event that was entirely ours disappears.
fn prune_managed(hooks: &mut Map<String, Value>) {
    prune_managed_except(hooks, &std::collections::HashSet::new());
}

/// [`prune_managed`], but the `(event, index)` groups in `keep` stay untouched.
fn prune_managed_except(
    hooks: &mut Map<String, Value>,
    keep: &std::collections::HashSet<(String, usize)>,
) {
    for (event, groups) in hooks.iter_mut() {
        let Value::Array(arr) = groups else { continue };
        let mut index = 0;
        arr.retain_mut(|group| {
            let kept = keep.contains(&(event.clone(), index));
            index += 1;
            if kept {
                return true;
            }
            let Some(inner) = group.get_mut("hooks").and_then(Value::as_array_mut) else {
                return true; // unrecognized shape — never touch it
            };
            let before = inner.len();
            inner.retain(|h| {
                h.get("command")
                    .and_then(Value::as_str)
                    .map(|c| !is_tuic_managed(c))
                    .unwrap_or(true)
            });
            // Drop the group only if WE emptied it (had hooks, now none).
            !(inner.is_empty() && before != inner.len())
        });
    }
    hooks.retain(|_event, groups| groups.as_array().map(|a| !a.is_empty()).unwrap_or(true));
}

/// `{matcher, hooks:[{type:command, command, statusMessage?}]}`.
fn managed_group(matcher: &str, cmd: &str, status: Option<&str>) -> Value {
    let mut hook = serde_json::json!({ "type": "command", "command": cmd });
    if let Some(status) = status {
        hook["statusMessage"] = Value::from(status);
    }
    serde_json::json!({ "matcher": matcher, "hooks": [ hook ] })
}

/// A group that holds only TUIC commands: one we wrote, safe to rewrite in place.
fn is_managed_group(group: &Value) -> bool {
    group
        .get("hooks")
        .and_then(Value::as_array)
        .is_some_and(|inner| {
            !inner.is_empty()
                && inner.iter().all(|h| {
                    h.get("command")
                        .and_then(Value::as_str)
                        .is_some_and(is_tuic_managed)
                })
        })
}

/// Rewrite our existing groups in place, in map order per event, and return
/// the `(event, index)` slots used plus the entries that found no slot.
fn rewrite_in_place<'a>(
    hooks: &mut Map<String, Value>,
    map: &'a [HookEntry],
    status: Option<&str>,
) -> (
    std::collections::HashSet<(String, usize)>,
    Vec<&'a HookEntry>,
) {
    let mut used = std::collections::HashSet::new();
    let mut unplaced = Vec::new();
    for entry in map {
        let (event, matcher, cmd) = entry;
        let slot = hooks
            .get_mut(*event)
            .and_then(Value::as_array_mut)
            .and_then(|arr| {
                let index = (0..arr.len()).find(|index| {
                    !used.contains(&(event.to_string(), *index)) && is_managed_group(&arr[*index])
                })?;
                arr[index] = managed_group(matcher, cmd, status);
                Some(index)
            });
        match slot {
            Some(index) => {
                used.insert((event.to_string(), index));
            }
            None => unplaced.push(entry),
        }
    }
    (used, unplaced)
}

/// Install the hook map into `settings`, preserving every non-TUIC entry.
/// `status` is written as `statusMessage` on every TUIC entry (Codex's label).
pub(crate) fn install(
    settings: &Path,
    map: &[HookEntry],
    status: Option<&str>,
) -> Result<(), String> {
    let mut root = load_root(settings)?;
    {
        let hooks = match root
            .entry("hooks".to_string())
            .or_insert_with(|| Value::Object(Map::new()))
        {
            Value::Object(m) => m,
            _ => {
                return Err(format!(
                    "{} `hooks` is not a JSON object",
                    settings.display()
                ));
            }
        };
        let (used, unplaced) = rewrite_in_place(hooks, map, status);
        prune_managed_except(hooks, &used); // idempotency: drop stale entries of ours
        for (event, matcher, cmd) in unplaced {
            if let Some(arr) = hooks
                .entry(event.to_string())
                .or_insert_with(|| Value::Array(Vec::new()))
                .as_array_mut()
            {
                arr.push(managed_group(matcher, cmd, status));
            }
        }
    }
    write_root(settings, &root)
}

/// Remove every TUIC-managed hook from `settings`, leaving user hooks intact.
/// A missing file is a no-op.
pub(crate) fn uninstall(settings: &Path) -> Result<(), String> {
    if !settings.exists() {
        return Ok(());
    }
    let mut root = load_root(settings)?;
    match root.get_mut("hooks") {
        Some(Value::Object(hooks)) => prune_managed(hooks),
        Some(_) => {
            return Err(format!(
                "{} `hooks` is not a JSON object",
                settings.display()
            ));
        }
        None => return Ok(()),
    }
    // Drop an emptied `hooks` key so the file is left pristine.
    if root
        .get("hooks")
        .and_then(Value::as_object)
        .map(Map::is_empty)
        .unwrap_or(false)
    {
        root.remove("hooks");
    }
    write_root(settings, &root)
}

/// Report whether the file's TUIC hooks match `map`. With `status` set, an
/// entry that lacks that `statusMessage` (an older install) is `Outdated`.
pub(crate) fn install_state(
    settings: &Path,
    map: &[HookEntry],
    status: Option<&str>,
) -> InstallState {
    let Ok(root) = load_root(settings) else {
        return InstallState::NotInstalled;
    };
    let Some(hooks) = root.get("hooks").and_then(Value::as_object) else {
        return InstallState::NotInstalled;
    };
    let mut present: Vec<String> = Vec::new();
    let mut labelled = true;
    for groups in hooks.values() {
        let Some(arr) = groups.as_array() else {
            continue;
        };
        for group in arr {
            let Some(inner) = group.get("hooks").and_then(Value::as_array) else {
                continue;
            };
            for h in inner {
                if let Some(c) = h.get("command").and_then(Value::as_str)
                    && is_tuic_managed(c)
                {
                    present.push(c.to_string());
                    if let Some(status) = status {
                        labelled &= h.get("statusMessage").and_then(Value::as_str) == Some(status);
                    }
                }
            }
        }
    }
    if present.is_empty() {
        return InstallState::NotInstalled;
    }
    let mut expected: Vec<String> = map.iter().map(|(_, _, c)| c.clone()).collect();
    present.sort();
    expected.sort();
    if labelled && present == expected {
        InstallState::Installed
    } else {
        InstallState::Outdated
    }
}

// ---------------------------------------------------------------------------
// Own-file strategy: TUIC owns the ENTIRE settings file (e.g. Grok's
// `~/.grok/hooks/tuic.json`). No merge needed — install writes the whole file,
// uninstall deletes it. Sibling files in the same directory are never touched.
// ---------------------------------------------------------------------------

/// Build a `{ "hooks": { event: [ { matcher?, hooks: [{type,command}] } ] } }`
/// document from the map. The `matcher` field is omitted when empty (lifecycle
/// events in Grok reject a matcher; an omitted matcher matches everything).
fn build_hooks_document(map: &[HookEntry]) -> Map<String, Value> {
    let mut hooks: Map<String, Value> = Map::new();
    for (event, matcher, cmd) in map {
        let group = if matcher.is_empty() {
            serde_json::json!({ "hooks": [ { "type": "command", "command": cmd } ] })
        } else {
            serde_json::json!({ "matcher": matcher, "hooks": [ { "type": "command", "command": cmd } ] })
        };
        hooks
            .entry(event.to_string())
            .or_insert_with(|| Value::Array(Vec::new()))
            .as_array_mut()
            .expect("event value is always an array")
            .push(group);
    }
    let mut root = Map::new();
    root.insert("hooks".to_string(), Value::Object(hooks));
    root
}

/// Own-file install: write the whole file (atomic, 0600). Creates parent dirs.
pub(crate) fn install_own_file(path: &Path, map: &[HookEntry]) -> Result<(), String> {
    write_root(path, &build_hooks_document(map))
}

/// Own-file uninstall: delete the file. Missing file is a no-op.
pub(crate) fn uninstall_own_file(path: &Path) -> Result<(), String> {
    if path.exists() {
        std::fs::remove_file(path).map_err(|e| format!("remove {}: {e}", path.display()))?;
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;
    use tempfile::TempDir;

    fn write(path: &Path, v: &Value) {
        std::fs::write(path, serde_json::to_vec_pretty(v).unwrap()).unwrap();
    }
    fn read(path: &Path) -> Value {
        serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap()
    }
    /// A settings file with a pre-existing user hook + an unrelated top-level key.
    fn user_hook_file() -> Value {
        json!({
            "hooks": {
                "PreToolUse": [
                    { "matcher": "Bash", "hooks": [ { "type": "command", "command": "wiz-guard.sh" } ] }
                ]
            },
            "otherKey": 42
        })
    }
    fn count_tuic(v: &Value) -> usize {
        let mut n = 0;
        if let Some(h) = v.get("hooks").and_then(|h| h.as_object()) {
            for groups in h.values() {
                let Some(arr) = groups.as_array() else {
                    continue;
                };
                for g in arr {
                    let Some(inner) = g.get("hooks").and_then(|x| x.as_array()) else {
                        continue;
                    };
                    for hk in inner {
                        if hk
                            .get("command")
                            .and_then(|c| c.as_str())
                            .map(is_tuic_managed)
                            .unwrap_or(false)
                        {
                            n += 1;
                        }
                    }
                }
            }
        }
        n
    }

    #[test]
    fn install_keeps_user_hook_and_adds_ours() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("settings.json");
        write(&path, &user_hook_file());
        let map = crate::agent_hook::claude_hook_map();
        install(&path, &map, None).unwrap();
        let v = read(&path);
        let pre = v["hooks"]["PreToolUse"].as_array().unwrap();
        assert!(
            pre.iter()
                .any(|g| g["hooks"][0]["command"] == "wiz-guard.sh"),
            "user hook must survive install"
        );
        assert_eq!(v["otherKey"], 42, "unrelated keys preserved");
        assert_eq!(count_tuic(&v), map.len(), "all our hooks added");
    }

    #[test]
    fn install_twice_equals_once() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("settings.json");
        write(&path, &user_hook_file());
        let map = crate::agent_hook::claude_hook_map();
        install(&path, &map, None).unwrap();
        let once = read(&path);
        install(&path, &map, None).unwrap();
        let twice = read(&path);
        assert_eq!(once, twice, "install must be idempotent");
        assert_eq!(count_tuic(&twice), map.len(), "no duplicate tuic hooks");
    }

    #[test]
    fn uninstall_removes_only_ours_byte_for_byte() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("settings.json");
        let original = user_hook_file();
        write(&path, &original);
        let map = crate::agent_hook::claude_hook_map();
        install(&path, &map, None).unwrap();
        assert!(count_tuic(&read(&path)) > 0);
        uninstall(&path).unwrap();
        let after = read(&path);
        assert_eq!(count_tuic(&after), 0, "all tuic hooks removed");
        assert_eq!(after, original, "file restored as if TUIC was never there");
    }

    #[test]
    fn install_creates_missing_file() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("nested/settings.json");
        assert!(!path.exists());
        let map = crate::agent_hook::claude_hook_map();
        install(&path, &map, None).unwrap();
        assert!(path.exists(), "missing file must be created");
        assert_eq!(count_tuic(&read(&path)), map.len());
    }

    #[test]
    fn non_object_root_errs_and_leaves_file_untouched() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("settings.json");
        std::fs::write(&path, b"[1,2,3]").unwrap();
        let before = std::fs::read(&path).unwrap();
        let map = crate::agent_hook::claude_hook_map();
        assert!(
            install(&path, &map, None).is_err(),
            "non-object root must error"
        );
        assert_eq!(
            std::fs::read(&path).unwrap(),
            before,
            "file must be untouched on error"
        );
    }

    #[test]
    fn non_object_hooks_errs_and_leaves_file_untouched() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("settings.json");
        std::fs::write(&path, br#"{"hooks": "nope"}"#).unwrap();
        let before = std::fs::read(&path).unwrap();
        let map = crate::agent_hook::claude_hook_map();
        assert!(
            install(&path, &map, None).is_err(),
            "non-object hooks must error"
        );
        assert_eq!(std::fs::read(&path).unwrap(), before);
    }

    // Catches (#2966-c31d): a reinstall that moves TUIC's group to the end of an
    // event shifts every later hook. Codex keys trust by position
    // (`hooks.json:stop:1:0`, recorded from codex 0.167.0 hooks/list), so the
    // other writer's hook lands on a key whose trusted hash belongs to TUIC's
    // command and Codex asks for review right after TUIC trusted its own hooks.
    #[test]
    fn reinstall_keeps_every_hook_at_its_position() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("hooks.json");
        let old = format!("old-stop {SENTINEL}");
        write(
            &path,
            &json!({ "hooks": { "Stop": [
                { "hooks": [ { "type": "command", "command": "user-first" } ] },
                { "matcher": "", "hooks": [ { "type": "command", "command": old } ] },
                { "hooks": [ { "type": "command", "command": "other-writer" } ] }
            ] } }),
        );
        let new = format!("new-stop {SENTINEL}");
        install(&path, &[("Stop", "", new.clone())], Some("label")).unwrap();
        let stop = read(&path)["hooks"]["Stop"].clone();
        let commands: Vec<&str> = stop
            .as_array()
            .unwrap()
            .iter()
            .map(|group| group["hooks"][0]["command"].as_str().unwrap())
            .collect();
        assert_eq!(commands, ["user-first", new.as_str(), "other-writer"]);
        assert_eq!(stop[1]["hooks"][0]["statusMessage"], "label");
    }

    #[test]
    fn install_state_not_installed_then_installed_then_outdated() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("settings.json");
        write(&path, &user_hook_file());
        let map = crate::agent_hook::claude_hook_map();
        assert_eq!(install_state(&path, &map, None), InstallState::NotInstalled);
        install(&path, &map, None).unwrap();
        assert_eq!(install_state(&path, &map, None), InstallState::Installed);
        let newer: Vec<HookEntry> = vec![("Stop", "", format!("new-cmd {SENTINEL}"))];
        assert_eq!(install_state(&path, &newer, None), InstallState::Outdated);
    }
}
